// Aggregate GitHub data into structured context for Claude
const commits = $input.first().json;
const allInputs = $input.all();
const issues = allInputs[1]?.json || [];
const prs = allInputs[2]?.json || [];

// Filter PRs to only merged (not just closed)
const mergedPRs = Array.isArray(prs) ? prs.filter(p => p.merged_at) : [];
const closedIssues = Array.isArray(issues) ? issues.filter(i => !i.pull_request) : [];

// Build commit summary
const commitMessages = Array.isArray(commits) 
  ? commits.slice(0, 50).map(c => `- ${c.commit?.message?.split('\n')[0] || 'unknown'} (${c.sha?.slice(0,7)})`).join('\n')
  : 'No commits';

// Build PR summary
const prSummary = mergedPRs.map(p => 
  `- #${p.number} ${p.title} by @${p.user?.login}`
).join('\n') || 'No merged PRs';

// Build issue summary  
const issueSummary = closedIssues.map(i =>
  `- #${i.number} ${i.title}`
).join('\n') || 'No closed issues';

const stats = {
  commitCount: Array.isArray(commits) ? commits.length : 0,
  mergedPRCount: mergedPRs.length,
  closedIssueCount: closedIssues.length
};

return {
  commits: commitMessages,
  pullRequests: prSummary,
  issues: issueSummary,
  stats,
  repo: `${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}`,
  week: `${$now.minus({days: 7}).toFormat('yyyy-MM-dd')} to ${$now.toFormat('yyyy-MM-dd')}`
};

// Build Claude API prompt from aggregated data
const data = $input.first().json;

const prompt = `You are a technical project manager writing a weekly development summary. 
Write a concise but informative narrative summary of this week's activity.

Repository: ${data.repo}
Period: ${data.week}

Stats: ${data.stats.commitCount} commits, ${data.stats.mergedPRCount} merged PRs, ${data.stats.closedIssueCount} closed issues.

## Commits this week:
${data.commits}

## Merged Pull Requests:
${data.pullRequests}

## Closed Issues:
${data.issues}

Write a summary with these sections:
1. **Overview** — 2-3 sentences summarizing the week
2. **Highlights** — Most important changes or milestones
3. **Pull Requests** — Key PRs merged and their impact
4. **Issues Resolved** — Notable closed issues
5. **What's Next** — Based on activity patterns, what to expect next week

Format in Markdown. Be specific, reference actual PR numbers and commit messages. Keep under 500 words.`;

return { prompt };

// Extract Claude's response and format final output
const response = $input.first().json;
const summary = response.content?.[0]?.text || 'No summary generated';

const header = `# Weekly Dev Summary\n\n**Repo:** ${$('Aggregate GitHub Data').first().json.repo}\n**Period:** ${$('Aggregate GitHub Data').first().json.week}\n\n---\n`;

const markdown = header + summary;

return {
  markdown,
  summary,
  timestamp: new Date().toISOString(),
  week: $('Aggregate GitHub Data').first().json.week
};

const str = $input.first().json.markdown;
const len = str.length;
const words = str.split(/\s+/).length;
return { success: true, summaryLength: len, wordCount: words };
